<?php
require_once __DIR__ . '/includes/functions.php';
$products = db()->query("SELECT p.*, c.name AS category_name, (SELECT AVG(rating) FROM product_reviews WHERE product_id=p.id AND status='approved') AS average_rating FROM products p LEFT JOIN categories c ON c.id=p.category_id WHERE p.is_active=1 AND p.is_featured=1 ORDER BY p.created_at DESC, p.id DESC LIMIT 4")->fetchAll();
$categories = db()->query('SELECT id,name,slug,image,description FROM categories WHERE is_active=1 ORDER BY name LIMIT 6')->fetchAll();
$bestSellers = db()->query("SELECT p.*,c.name AS category_name,(SELECT AVG(rating) FROM product_reviews WHERE product_id=p.id AND status='approved') AS average_rating,sold.quantity_sold AS sold FROM products p JOIN (SELECT oi.product_id,SUM(oi.quantity) AS quantity_sold FROM order_items oi JOIN orders o ON o.id=oi.order_id WHERE o.status<>'cancelled' GROUP BY oi.product_id) sold ON sold.product_id=p.id LEFT JOIN categories c ON c.id=p.category_id WHERE p.is_active=1 ORDER BY sold.quantity_sold DESC LIMIT 4")->fetchAll();
$featuredIds = array_map('intval', array_column($products, 'id'));
$latestStmt = db()->prepare("SELECT p.*,c.name AS category_name,(SELECT AVG(rating) FROM product_reviews WHERE product_id=p.id AND status='approved') AS average_rating FROM products p LEFT JOIN categories c ON c.id=p.category_id WHERE p.is_active=1" . ($featuredIds ? ' AND p.id NOT IN (' . implode(',', array_fill(0, count($featuredIds), '?')) . ')' : '') . " ORDER BY p.created_at DESC, p.id DESC LIMIT 4");
$latestStmt->execute($featuredIds);
$latest = $latestStmt->fetchAll();
$services = db()->query("SELECT name, slug, description FROM services WHERE is_active=1 ORDER BY id LIMIT 3")->fetchAll();
$testimonials = db()->query('SELECT customer_name, location, quote FROM testimonials WHERE is_active=1 ORDER BY created_at DESC LIMIT 2')->fetchAll();
$galleryPreview=db()->query('SELECT title,image FROM gallery WHERE is_active=1 ORDER BY created_at DESC LIMIT 3')->fetchAll();
